class CounterService {
  private hits = 0;
  bump() { return ++this.hits; }
}

// CounterService is in ONE module's providers; two controllers inject it.
// Request 1 hits ControllerA -> counter.bump()
// Request 2 hits ControllerB -> counter.bump()
// Request 3 hits ControllerA -> counter.bump()

